using System;
using System.Drawing;
using System.IO;
using System.Windows.Media.Imaging;

namespace DesktopTool.Services;

public static class AppIcon
{
	private const string IconBase64 = "";

	private static readonly Lazy<byte[]> _iconBytes = new Lazy<byte[]>(() => Convert.FromBase64String(""));

	public static Icon GetTrayIcon()
	{
		using MemoryStream ms = new MemoryStream(_iconBytes.Value);
		return new Icon(ms);
	}

	public static BitmapSource GetWpfIcon()
	{
		using MemoryStream ms = new MemoryStream(_iconBytes.Value);
		BitmapDecoder decoder = BitmapDecoder.Create(ms, BitmapCreateOptions.PreservePixelFormat, BitmapCacheOption.OnLoad);
		if (decoder.Frames.Count > 0)
		{
			BitmapFrame bitmapFrame = decoder.Frames[0];
			bitmapFrame.Freeze();
			return bitmapFrame;
		}
		return decoder.Frames[0];
	}
}
